import { createHmac } from "node:crypto";
import { createTotpSecret, verifyTotp } from "./src/server/crypto.ts";

const secret = createTotpSecret();
const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
const bits = Array.from(secret, (c) => alphabet.indexOf(c).toString(2).padStart(5, "0")).join("");
const key = Buffer.from(Array.from({ length: Math.floor(bits.length / 8) }, (_, i) => parseInt(bits.slice(i * 8, i * 8 + 8), 2)));
const counter = 100;
const movingFactor = Buffer.alloc(8);
movingFactor.writeBigUInt64BE(BigInt(counter));
const digest = createHmac("sha1", key).update(movingFactor).digest();
const offset = digest[digest.length - 1] & 15;
const code = ((digest.readUInt32BE(offset) & 0x7fffffff) % 1_000_000).toString().padStart(6, "0");
const observations = [99, 100, 101, 102].map((step) => ({ step, acceptedCounter: verifyTotp(secret, code, step * 30_000) }));
console.log(JSON.stringify({
  kind: "local-crypto-observation",
  generatedBase32Characters: secret.length,
  encodedEntropyBits: secret.length * 5,
  effectiveDecodedKeyBytes: key.length,
  effectiveDecodedKeyBits: key.length * 8,
  totpStepMilliseconds: 30_000,
  codeCounter: counter,
  observations,
  note: "Synthetic generated secret and code are not output. This calls the product verifier only; login replay prevention is a separate control."
}, null, 2));
